const grid=document.querySelector(".gallery-grid"),lightbox=document.getElementById("lightbox"),lightboxImg=document.querySelector(".lightbox-img"),closeBtn=document.querySelector(".close"),prevBtn=document.querySelector(".prev"),nextBtn=document.querySelector(".next"),images=Array.from(document.querySelectorAll(".gallery-grid img"));let currentIndex=0;images.forEach((e=>{const t=e.src,n=`photos/thumb/${t.split("/").pop().replace(/\.[^/.]+$/,"")}.webp`;e.dataset.full=t,e.src=n,e.style.cursor="pointer"}));const preloadImage=e=>{if(e>=0&&e<images.length){(new Image).src=images[e].dataset.full}};function updateLightboxImage(){const e=images[currentIndex],t=e.dataset.full||e.src;lightboxImg.src=t;const n=(currentIndex+1)%images.length,o=(currentIndex-1+images.length)%images.length;preloadImage(n),preloadImage(o)}function openLightbox(e){currentIndex=e,updateLightboxImage(),lightbox.classList.remove("hidden")}function closeLightbox(){lightbox.classList.add("hidden"),lightboxImg.src=""}function showNext(e){e&&e.stopPropagation(),currentIndex=(currentIndex+1)%images.length,updateLightboxImage()}function showPrev(e){e&&e.stopPropagation(),currentIndex=(currentIndex-1+images.length)%images.length,updateLightboxImage()}grid.addEventListener("click",(e=>{if("IMG"===e.target.tagName){const t=images.indexOf(e.target);-1!==t&&openLightbox(t)}})),closeBtn.addEventListener("click",closeLightbox),nextBtn.addEventListener("click",showNext),prevBtn.addEventListener("click",showPrev),document.addEventListener("keydown",(e=>{lightbox.classList.contains("hidden")||("Escape"===e.key&&closeLightbox(),"ArrowRight"===e.key&&showNext(),"ArrowLeft"===e.key&&showPrev())})),lightbox.addEventListener("click",(e=>{e.target===lightbox&&closeLightbox()}));